     TIMESTAMP WITH TIME ZONE '2026-03-01 00:00:00+00', TIMESTAMP WITH TIME ZONE '2026-03-01 00:00:00+00'),
    ('00000000-0000-0000-0000-000000000002', 'sam.demo@example.test',
