                          description, transaction_type, created_at, updated_at)
SELECT md5('synthetic-seed-transaction-' || sequence_number)::uuid,
       CASE WHEN sequence_number <= 108 THEN '00000000-0000-0000-0000-000000000001'::uuid ELSE '00000000-0000-0000-0000-000000000002'::uuid END,
       CASE WHEN sequence_number <= 108 THEN
            CASE (sequence_number - 1) % 9 WHEN 0 THEN '00000000-0000-0000-0000-000000000011'::uuid WHEN 1 THEN '00000000-0000-0000-0000-000000000014'::uuid WHEN 2 THEN '00000000-0000-0000-0000-000000000015'::uuid WHEN 3 THEN '00000000-0000-0000-0000-000000000016'::uuid WHEN 4 THEN '00000000-0000-0000-0000-000000000014'::uuid WHEN 5 THEN '00000000-0000-0000-0000-000000000015'::uuid WHEN 6 THEN '00000000-0000-0000-0000-000000000016'::uuid WHEN 7 THEN '00000000-0000-0000-0000-000000000014'::uuid ELSE '00000000-0000-0000-0000-000000000015'::uuid END
       ELSE CASE (sequence_number - 1) % 9 WHEN 0 THEN '00000000-0000-0000-0000-000000000021'::uuid WHEN 1 THEN '00000000-0000-0000-0000-000000000024'::uuid WHEN 2 THEN '00000000-0000-0000-0000-000000000025'::uuid WHEN 3 THEN '00000000-0000-0000-0000-000000000026'::uuid WHEN 4 THEN '00000000-0000-0000-0000-000000000024'::uuid WHEN 5 THEN '00000000-0000-0000-0000-000000000025'::uuid WHEN 6 THEN '00000000-0000-0000-0000-000000000026'::uuid WHEN 7 THEN '00000000-0000-0000-0000-000000000024'::uuid ELSE '00000000-0000-0000-0000-000000000025'::uuid END
       END,
       CASE WHEN (sequence_number - 1) % 9 = 0 THEN 5000.0000 ELSE (15 + ((sequence_number * 17) % 85))::numeric(19,4) END,
       'USD', 1.00000000,
       (DATE '2026-03-01' + (((sequence_number - 1) % 6) * INTERVAL '1 month') + (((sequence_number - 1) % 28) * INTERVAL '1 day'))::date,
       'Synthetic demo transaction ' || sequence_number,
       CASE WHEN (sequence_number - 1) % 9 = 0 THEN 'INCOME' ELSE 'EXPENSE' END,
       TIMESTAMP WITH TIME ZONE '2026-03-01 00:00:00+00', TIMESTAMP WITH TIME ZONE '2026-03-01 00:00:00+00'
FROM generate_series(1, 216) AS sequence_number;
